int fib(n) {
    mem[n + 2];  // por si n es 0 o 1
    mem[0] = 0;
    mem[1] = 1;
    for (i = 2; i < n + 1; i++) {
        mem[i] = mem[i - 1] + mem[i - 2];
    }
    return mem[n];
}

